body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100vh;
  /* iPad */
  height: 100svh;
  display: flex;
  flex-direction: column;
  /* Pull-to-Refresh防止 */
  overscroll-behavior-y: none;
  /* 注意　HTML5版も影響をうける */
  overflow: hidden;
}

#axp_main {
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  color: #fff;
  background-color: #000;
  font-size: 15px;
  width: 100%;
  margin: 0 auto;
  padding: 0;
  display: none;
  flex-grow: 1;
  flex-direction: column;
  overflow: hidden;
  font-family: sans-serif;
}

/* 詳細度0.0.0でツールの要素全体に指定 */
:where(#axp_main) * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* メインのタブ制御 */
#axp_main_div_tab {
  display: flex;
  align-items: flex-end;
  min-height: 30px;
}

/* 見出し枠 */
#axp_main_div_tab_menu {
  list-style-type: none;
  display: flex;
}

/* 見出し */
#axp_main_div_tab_menu>div {
  display: block;
  width: 98px;
  margin: 0;
  padding: 2px 0;
  text-align: center;
  border-top: 2px solid #000;
  border-left: 0px solid #000;
  border-right: 2px solid #000;
  border-radius: 10px 10px 0 0;
  background: #333;
  box-sizing: border-box;
  cursor: pointer;
}

/* 見出しにカーソルを当てた時 */
#axp_main_div_tab_menu>div:hover {
  background: #555;
}

/* 選択されている見出し */
#axp_main_div_tab_menu>div[data-selected="true"] {
  background: #777;
}

/* ハンバーガーメニュー */
#axp_main_label_hamburger {
  /* 通常は非表示 */
  display: none;
  height: 100%;
  width: 30px;
  cursor: pointer;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  margin: 0 8px;
}

/* ハンバーガーメニューチェックボックス */
#axp_main_checkbox_hamburger {
  display: none;
}

/* ブラウザの横幅が599px以下の場合 */
@media (max-width: 599px) {

  /* ハンバーガーメニュー表示 */
  #axp_main_label_hamburger {
    display: flex;
  }

  #axp_main_div_tab_menu {
    position: absolute;
    background: #333;
    top: 0;
    margin-top: 30px;
    left: 0;
    flex-direction: column;
    width: 100%;
    justify-content: center;
    align-items: center;
    overflow: hidden;
    z-index: 6000;
  }

  #axp_main_checkbox_hamburger~div>div {
    height: 0;
    margin: 0;
    padding: 0;
    border: 0;
    transition: height 400ms cubic-bezier(0.23, 1, 0.32, 1);
  }

  #axp_main_checkbox_hamburger:checked~div>div {
    border: 1px solid #333;
    height: 2.5em;
    padding: 0.5em;
    transition: height 400ms cubic-bezier(0.23, 1, 0.32, 1);
  }

  #axp_main_div_tab_menu>div {
    display: flex;
    justify-content: center;
    margin: 0;
    padding: 0.5em 0;
    width: 100%;
    border-radius: 10px 10px 10px 10px;
  }
}

/* タブ横のテキスト */
#axp_main_div_headerText {
  padding: 4px 10px 0;
  color: #fff;
  overflow: hidden;
  white-space: pre;
  flex-grow: 1;
  cursor: pointer;
  text-overflow: ellipsis;
}

/* タブ横のテキストクリック時、全文表示 */
#axp_main_div_headerText:active {
  overflow: visible;
  white-space: normal;
}

/* タブにより切り替わる画面 */
#axp_main_div_tabContent>article {
  display: none;
  flex-grow: 1;
  flex-direction: column;
  overflow: hidden;
}

/* inputのフォントサイズ指定 */
#axp_main_div_tabContent input {
  font-size: 13px;
}

/* タブ：キャンバス */
#axp_canvas {
  width: 100%;
  overflow: hidden;
  position: relative;
  flex-grow: 1;
}

/* キャンバス外の灰色部分 */
#axp_canvas_div_grayBackground {
  width: 100%;
  height: 100%;
  background-color: #777;
}

/* メインキャンバス */
#axp_canvas_canvas_main {
  position: absolute;
  image-rendering: pixelated;
  z-index: 100;
}

/* 補助線 */
#axp_canvas_div_grid {
  /* イベントを受け取らない（重要） */
  pointer-events: none;
  image-rendering: auto;
  position: absolute;
  z-index: 600;
}

/* 座標表示用領域 */
#axp_canvas_div_pointerPosition {
  position: absolute;
  right: 0;
  bottom: 0;
  font-family: monospace;
  font-size: 18px;
  font-weight: 500;
  color: #fff;
  background: rgba(0, 0, 0, 0.7);
  box-shadow: #000;
  z-index: 800;
}

/* 回転操作子グループ（ハンドツール時に上部中央へ表示） */
#axp_canvas_div_rotateGroup {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 3000;
  display: flex;
  gap: 4px;
}

#axp_canvas_div_rotateGroup > .axpc_overlay_knob,
#axp_canvas_div_rotateGroup > .axpc_overlay_btn {
  position: static;
}

#axp_canvas_div_rotateLeft {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
}

#axp_canvas_div_rotateHandle {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_1___});
}

#axp_canvas_div_rotateRight {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_2___});
}

/* なげなわ操作子グループ（なげなわ変形中に上部中央へ表示） */
#axp_canvas_div_nagenawaGroup {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 3000;
  display: flex;
  gap: 4px;
}

#axp_canvas_div_nagenawaGroup > .axpc_overlay_knob,
#axp_canvas_div_nagenawaGroup > .axpc_overlay_btn {
  position: static;
}

#axp_canvas_div_nagenawaScale {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_3___});
}

#axp_canvas_div_nagenawaRotate {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_1___});
}

#axp_canvas_div_nagenawaFlip {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_4___});
}

#axp_canvas_div_nagenawaDuplicate {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_5___});
}

#axp_canvas_div_nagenawaFinish {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_6___});
}

/* デバッグ情報 */
#axp_canvas_div_debugInfo {
  position: absolute;
  top: 0;
  left: 0;
  font-family: monospace;
  font-size: 1em;
  background: rgba(0, 0, 0, 0.7);
  box-shadow: #000;
  z-index: 900;
  height: 50%;
  max-height: 95%;
  resize: both;
  overflow: hidden;
}

#axp_canvas_div_debugInfo>div:nth-of-type(1) {
  font-family: monospace;
  color: #fff;
  font-size: 1em;
  height: 24px;
  overflow: hidden;
}

#axp_canvas_div_debugInfo>div:nth-of-type(2) {
  font-family: monospace;
  font-size: 1em;
  color: #fff;
  background: rgba(0, 0, 0, 0);
  min-width: 360px;
  height: calc(100% - 24px);
  overflow-x: hidden;
  overflow-y: scroll;
}

/* カーソル位置に表示するペンの太さ表示*/
#axp_canvas_div_penCursor {
  pointer-events: none;
  position: absolute;
  border: solid 2px rgba(0, 0, 0, 0.3);
  z-index: 700;
}


#axp_main_div_tabContent,
#axp_config,
#axp_config_div_menu {
  display: flex;
  flex-grow: 1;
  flex-direction: column;
  overflow: hidden;
}

/* タブ：設定 */
#axp_config_div_content {
  flex-grow: 1;
}

/* タブ：投稿 */
#axp_post {
  flex-grow: 1;
  overflow: auto;
}

/* フッター領域 */
#axp_footer {
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  background-color: #222;
  color: #ddd;
  display: flex;
  flex-basis: 31px;
}

#axp_footer_div_message {
  background-color: rgba(0, 0, 0, 0);
  font-size: 15px;
  font-family: sans-serif;
  padding: 4px;
}

#axp_footer_div_icon {
  margin-left: 8px;
  margin-top: 2px;
