}

/* 混色ペンのプリセットボタン */
#axp_pen_div_diffusionPreset {
    display: flex;
    flex-flow: column;
    gap: 2px;
    margin-top: 4px;
}

.axpc_pen_diffpreset {
    width: 100%;
    height: 18px;
    font-size: 13px;
    line-height: 1;
    padding: 0 4px;
    border: 1px solid #888;
    border-radius: 3px;
    background: #555;
    color: #eee;
    cursor: pointer;
    text-align: center;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.axpc_pen_diffpreset:active {
    background: #333;
}

/* 反映中 (現在値が格納値と一致) の明示 */
.axpc_pen_diffpreset[data-active="true"] {
    background: #000;
    color: #fff;
    border-color: #000;
}

/* 混色ペンの詳細設定開閉ボタン */
#axp_pen_button_diffusionDetail {
    width: 100%;
    height: 17px;
    font-size: 12px;
    line-height: 1;
    padding: 0 4px;
    margin-top: 4px;
    border: 1px dashed #888;
    border-radius: 3px;
    background: none;
    color: #eee;
    cursor: pointer;
    text-align: left;
}

/* 太さクイックボタン */
#axp_pen_div_quickSize {
    display: flex;
    gap: 2px;
    margin-top: 4px;
    width: 104px;
}
#axp_pen_div_quickSize.axpc_NONE {
    display: none;
}
.axpc_pen_quicksize {
    flex: 1;
    height: 28px;
    border: 1px solid #888;
    border-radius: 3px;
    background: #555;
    color: #eee;
    cursor: pointer;
    padding: 0;
    line-height: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    -webkit-user-select: none;
    user-select: none;
}
.axpc_pen_quicksize:active {
    background: #333;
}
.axpc_pen_quicksize .axpc_qs_label {
    font-size: 7px;
    line-height: 1;
}
.axpc_pen_quicksize .axpc_qs_num {
    font-size: 14px;
    font-weight: bold;
